@startuml

class Museum {
  + Name : string
}

class Location {
  + Name : string
}

class Exhibition {
  + Title : string
  + OpeningDate : date
}

class Employee {
  + Name : string
}

class ExhibitionItem {
  + Description : string
}

class Piece {
  + Description : string
}

class Collector {
  + Name : string
}

class RequestedPiece {
  + Status : string
}

Museum "1" -- "*" Location
Location "1" -- "*" Exhibition

Exhibition "*" -- "1" Employee : coordinator
Employee "0..1" -- "0..1" Employee : coach

Exhibition "1" -- "*" ExhibitionItem
ExhibitionItem "1" -- "*" RequestedPiece
RequestedPiece "*" -- "1" Piece
RequestedPiece "*" -- "1" Collector

@enduml

